export async function executeGeneratedCommand(commandName: string, params: Record<string, unknown> = {}): Promise<unknown> {
  const schema = generatedCommandSchemas.find((entry) => entry.name === commandName);
  if (!schema) {
    throw new Error(`Unknown generated command: ${commandName}`);
  }
  const handlerUrl = new URL(`../../../otto-command-service/src/handlers/${schema.routing.handlerModule}`, import.meta.url);
  const mod = await import(handlerUrl.href);
  const fn = mod[schema.routing.handlerExport];
  if (typeof fn !== "function") {
    throw new Error(`Handler export not found for command ${commandName}: ${schema.routing.handlerExport}`);
  }
  return fn(params);
}
